package consensus

import (
	"crypto/ed25519"
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

type testKey struct {
	priv ed25519.PrivateKey
	pub  ed25519.PublicKey
}

func genKeys(t *testing.T, n int) []testKey {
	t.Helper()
	keys := make([]testKey, n)
	for i := range keys {
		pub, priv, err := ed25519.GenerateKey(rand.Reader)
		if err != nil {
			t.Fatal(err)
		}
		keys[i] = testKey{priv: priv, pub: pub}
	}
	return keys
}

func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
	t.Helper()
	dir := t.TempDir()
	vals := make([][]byte, len(keys))
	for i, k := range keys {
		vals[i] = k.pub
	}
	n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
	if err != nil {
		t.Fatal(err)
	}
	return n, dir
}

func reason(err error) string {
	var re *RejectError
	if errors.As(err, &re) {
		return re.Reason
	}
	return ""
}

// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
func TestInitialState(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 10)
