package consensus

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

// 本文件钉住“主动结束未确认轮次”的原子落盘回归保障。
//
// 场景：节点已有一块确认历史（第 1 轮确认，当前处于第 2 轮）。第 2 轮的本地
// 提议与一个竞争候选已经登记，两者引用同一批池内交易，其中有共享交易也有仅被
// 单个候选引用的交易；不同验证者分别投给两个候选但都未达确认门槛。池内还有
// 未被任何候选引用的排队交易。各交易到期轮次覆盖“恰好等于下一轮（2→3 后失效）”
// 与“晚于下一轮（2→3 后仍排队）”两种情况。
//
// 当这次 EndRound 因节点状态写入失败而返回错误时：返回轮次值必须为 0；
// 候选落选标记、交易回排队、轮次前进与到期失效作为一次完整操作必须整体不生效——
// 等待投票的交易不提前回排队，排队中的交易不提前过期，确认历史、账户序号与缺口
// 全部保持操作前结果；磁盘文件与临时文件清理、重开节点看到的状态同内存一致。
//
// 保存恢复正常后，在仍处于原轮次的节点上再次 EndRound 才进入下一轮：
// 旧轮明确标记未确认结束、两候选均落选、原投票仍可查；候选交易全部回到排队
// （共享交易只占一个池位、只出现一次）；到期轮次不大于新轮次的交易从待处理
// 列表移除并可查为 expired，包括此前没有被候选引用的交易；此次结束不增加确认块、
// 不推进账户已确认序号。本组测试不改变现有公开入口、候选规则与确认门槛。

// round2Spec 描述第 2 轮场景中每笔交易的布局。
type round2Spec struct {
	tx       *Transaction
	expiry   uint64 // 提交时使用的到期轮次
	fee      uint64 // 提交时使用的费用
	content  string
	inLocal  bool // 是否在本地提议中
	inAlt    bool // 是否在竞争候选中
	sender   int  // 发送者索引（相对全局 keys，用于账户查询与 gap 检查）
	sequence uint64
}

// buildRoundTwoPending 在第 1 轮确认历史之上构造第 2 轮未决场景：
// 本地提议、竞争候选、分别投给两候选但未达门槛的投票，以及若干候选外排队交易。
// 返回本地提议视图、竞争候选标识与场景交易清单。
func buildRoundTwoPending(t *testing.T, n *Node, keys []testKey) (ProposalView, string, []round2Spec) {
	t.Helper()

	// 账户 0 在第 1 轮已确认序号 1；第 2 轮从序号 2 起。其余账户已确认序号 0。
	//
	// 候选内交易（账户 0，序号 2..5，候选最多 4 笔、不超单块上限 10）：
	//   shared   seq2 fee10 expiry=3（恰好等于下一轮）：两候选共享，结束后应过期
	//   localOnly seq3 fee20 expiry=100：仅本地提议引用，结束后回排队且未到期
	//   altOnly   seq4 fee30 expiry=3：仅竞争候选引用，结束后应过期
	//   sharedLate seq5 fee40 expiry=100：两候选共享，结束后回排队且未到期
	// 候选外排队交易覆盖“引用情况 × 到期情况”的其余格子：
	//   queuedExpire 账户1 seq1 expiry=3：未被引用、恰好下一轮到期 -> 过期
	//   queuedLate   账户2 seq1 expiry=100：未被引用、晚于下一轮 -> 排队
	//   gapExpire    账户3 seq2 expiry=3：未被引用、恰好下一轮到期 -> 过期并留下序号缺口
	//   gapLate      账户3 seq3 expiry=100：未被引用、晚于下一轮 -> 排队，与 gapExpire 同账户
	specs := []round2Spec{
		{tx: NewTransaction(keys[0].priv, 2, []byte("shared"), 10, 3), expiry: 3, fee: 10, content: "shared", inLocal: true, inAlt: true, sender: 0, sequence: 2},
		{tx: NewTransaction(keys[0].priv, 3, []byte("local-only"), 20, 100), expiry: 100, fee: 20, content: "local-only", inLocal: true, inAlt: false, sender: 0, sequence: 3},
		{tx: NewTransaction(keys[0].priv, 4, []byte("alt-only"), 30, 100),  // altOnly 不过期（expiry 100），保证竞争候选独有交易也有回排队的
			expiry: 100, fee: 30, content: "alt-only", inLocal: false, inAlt: true, sender: 0, sequence: 4},
		{tx: NewTransaction(keys[0].priv, 5, []byte("shared-late"), 40, 100), expiry: 100, fee: 40, content: "shared-late", inLocal: true, inAlt: true, sender: 0, sequence: 5},
		{tx: NewTransaction(keys[1].priv, 1, []byte("queued-expire"), 1, 3), expiry: 3, fee: 1, content: "queued-expire", inLocal: false, inAlt: false, sender: 1, sequence: 1},
		{tx: NewTransaction(keys[2].priv, 1, []byte("queued-late"), 1, 100), expiry: 100, fee: 1, content: "queued-late", inLocal: false, inAlt: false, sender: 2, sequence: 1},
		{tx: NewTransaction(keys[3].priv, 2, []byte("gap-expire"), 1, 3), expiry: 3, fee: 1, content: "gap-expire", inLocal: false, inAlt: false, sender: 3, sequence: 2},
		{tx: NewTransaction(keys[3].priv, 3, []byte("gap-late"), 1, 100), expiry: 100, fee: 1, content: "gap-late", inLocal: false, inAlt: false, sender: 3, sequence: 3},
	}
	for _, s := range specs {
		if _, err := n.Submit(s.tx); err != nil {
			t.Fatalf("submit %s: %v", s.content, err)
		}
	}

	// 本地提议由打包规则确定；本场景要求恰好把四笔候选内交易按费用升序选入。
	local, err := n.Propose()
	if err != nil {
		t.Fatal(err)
	}
	wantLocal := []string{
		specs[0].tx.ID(), // shared      fee10
		specs[1].tx.ID(), // local-only  fee20
		specs[2].tx.ID(), // alt-only    fee30
		specs[3].tx.ID(), // shared-late fee40
	}
	if fmt.Sprint(local.TxIDs) != fmt.Sprint(wantLocal) {
		t.Fatalf("setup: local proposal tx order = %v, want %v", local.TxIDs, wantLocal)
	}
	sharedEarly := specs[0].tx
	sharedLate := specs[3].tx
	localOnly := specs[1].tx
	altOnly := specs[2].tx

	// 竞争候选：共享交易居中，独有交易分别位于两端，交易顺序与本地方案不同。
	altList := []string{altOnly.ID(), sharedEarly.ID(), sharedLate.ID()}
	alt, err := n.RegisterCandidate(2, altList)
	if err != nil {
		t.Fatal(err)
	}
	if alt.BlockID == local.BlockID {
		t.Fatal("setup: competitor block id must differ from local proposal")
	}

	// 四名验证者，确认门槛为票数严格超过 2/3（即至少 3 票）。
	// 验证者 0 投本地（1 票），验证者 1 投竞争候选（1 票）；验证者 2、3 未投票。
	// 两个候选都只有 1 票，均未决。
	voteRes, err := n.Vote(keys[0].pub, 2, local.BlockID)
	if err != nil || !voteRes.Counted || voteRes.Confirmed {
		t.Fatalf("local vote: %+v %v", voteRes, err)
	}
	voteRes, err = n.Vote(keys[1].pub, 2, alt.BlockID)
	if err != nil || !voteRes.Counted || voteRes.Confirmed {
		t.Fatalf("competitor vote: %+v %v", voteRes, err)
	}
	return local, alt.BlockID, specs
}

// assertRoundTwoPending 断言节点正处于第 2 轮结束前/失败后的完整未决状态。
// 参数与 buildRoundTwoPending 的返回一一对应；confirmedBlock 为第 1 轮留下的
// 确认块，结束第 2 轮不得改动它。
func assertRoundTwoPending(t *testing.T, n *Node, local ProposalView, altID string, specs []round2Spec, confirmedBlock Block, keys []testKey) {
	t.Helper()

	// 轮次仍是 2，确认历史仍是第 1 轮那一块。
	if n.CurrentRound() != 2 {
		t.Fatalf("current round = %d, want 2", n.CurrentRound())
	}
	if n.Height() != 1 {
		t.Fatalf("confirmed height = %d, want 1", n.Height())
	}
	blk, err := n.BlockAt(1)
	if err != nil {
		t.Fatal(err)
	}
	if blk != confirmedBlock {
		t.Fatalf("confirmed block changed: got %+v, want %+v", blk, confirmedBlock)
	}
	if latest, ok := n.LatestBlock(); !ok || latest != confirmedBlock {
		t.Fatalf("latest block = %+v ok=%v, want %+v", latest, ok, confirmedBlock)
	}

	// 旧轮（第 1 轮）仍是确认结束、有详情的历史轮次。
	rc1, err := n.Candidates(1)
	if err != nil {
		t.Fatal(err)
	}
	if !rc1.Ended || rc1.UnconfirmedEnd || !rc1.HasRecords || len(rc1.Candidates) != 1 {
		t.Fatalf("round 1 history changed: %+v", rc1)
	}

	// 当前轮：未决出、有记录，两个候选保持 pending，标识、顺序、投票与未投票名单不变。
	rc, err := n.Candidates(2)
	if err != nil {
		t.Fatal(err)
	}
	if rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
		t.Fatalf("round 2 must stay pending with records: %+v", rc)
	}
	if len(rc.Candidates) != 2 {
		t.Fatalf("candidate count = %d, want 2", len(rc.Candidates))
	}
	wantUnvoted := hexKeys([][]byte{keys[2].pub, keys[3].pub})
	if got := hexKeys(rc.Unvoted); fmt.Sprint(got) != fmt.Sprint(wantUnvoted) {
		t.Fatalf("unvoted = %x, want %x", rc.Unvoted, [][]byte{keys[2].pub, keys[3].pub})
	}
	var gotLocal, gotAlt *CandidateView
	for i := range rc.Candidates {
		switch rc.Candidates[i].BlockID {
		case local.BlockID:
			gotLocal = &rc.Candidates[i]
		case altID:
			gotAlt = &rc.Candidates[i]
		}
	}
	if gotLocal == nil || gotAlt == nil {
		t.Fatalf("both candidates must remain present: %+v", rc.Candidates)
	}
	if !gotLocal.Local || gotLocal.Result != CandidatePending {
		t.Fatalf("local candidate must stay pending: %+v", gotLocal)
	}
	if len(gotLocal.Voters) != 1 || fmt.Sprintf("%x", gotLocal.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
		t.Fatalf("local candidate voters = %x, want only validator 0", gotLocal.Voters)
	}
	wantLocalOrder := []string{specs[0].tx.ID(), specs[1].tx.ID(), specs[2].tx.ID(), specs[3].tx.ID()}
	if fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(wantLocalOrder) {
		t.Fatalf("local tx order = %v, want %v", gotLocal.TxIDs, wantLocalOrder)
	}
	if gotAlt.Local || gotAlt.Result != CandidatePending {
		t.Fatalf("competitor must stay pending: %+v", gotAlt)
	}
	wantAltOrder := []string{specs[2].tx.ID(), specs[0].tx.ID(), specs[3].tx.ID()}
	if fmt.Sprint(gotAlt.TxIDs) != fmt.Sprint(wantAltOrder) {
		t.Fatalf("alt tx order = %v, want %v", gotAlt.TxIDs, wantAltOrder)
	}
	if len(gotAlt.Voters) != 1 || fmt.Sprintf("%x", gotAlt.Voters[0]) != fmt.Sprintf("%x", keys[1].pub) {
		t.Fatalf("competitor voters = %x, want validator 1", gotAlt.Voters)
	}

	// 本地提议视图：标识与交易顺序原样。
	p, ok := n.Proposal()
	if !ok {
		t.Fatal("local proposal must still be available")
	}
	if p.BlockID != local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(wantLocalOrder) {
		t.Fatalf("local proposal changed: id=%s txs=%v, want id=%s txs=%v",
			p.BlockID, p.TxIDs, local.BlockID, wantLocalOrder)
	}

	// 交易状态：候选内四笔仍 proposed（不提前回排队）；候选外四笔保持 queued（不提前过期）。
	for _, s := range specs {
		info := n.mustTx(t, s.tx.ID())
		want := StatusQueued
		if s.inLocal || s.inAlt {
			want = StatusProposed
		}
		if info.Status != want {
			t.Fatalf("tx %s status = %s, want %s", s.content, info.Status, want)
		}
		if info.BlockHeight != 0 || info.BlockID != "" {
			t.Fatalf("tx %s must not gain a block reference: height=%d block=%q",
				s.content, info.BlockHeight, info.BlockID)
		}
	}

	// 账户查询：确认序号、待处理集合与缺口说明保持操作前结果。
	// 账户0：第 1 轮已确认 seq1；待处理 seq2..5 全部 waiting-vote，无缺口。
	assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{
		specs[0].tx.ID(): "waiting-vote",
		specs[1].tx.ID(): "waiting-vote",
		specs[2].tx.ID(): "waiting-vote",
		specs[3].tx.ID(): "waiting-vote",
	})
	if a := n.Account(keys[0].pub); a.Gap != 0 {
		t.Fatalf("account 0 gap = %d, want 0", a.Gap)
	}
	// 账户1：queuedExpire waiting-pack。
	assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{
		specs[4].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[1].pub); a.Gap != 0 {
		t.Fatalf("account 1 gap = %d, want 0", a.Gap)
	}
	// 账户2：queuedLate waiting-pack。
	assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
		specs[5].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[2].pub); a.Gap != 0 {
		t.Fatalf("account 2 gap = %d, want 0", a.Gap)
	}
	// 账户3：没有 seq1，待处理 seq2/seq3 仍 waiting-pack；最早缺口为 1。
	assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{
		specs[6].tx.ID(): "waiting-pack",
		specs[7].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[3].pub); a.Gap != 1 {
		t.Fatalf("account 3 gap = %d, want 1", a.Gap)
	}
}

// assertRoundThreeEnded 断言保存恢复后再次 EndRound 成功进入第 3 轮后的状态：
// 两候选落选、旧票保留；未到期候选交易回排队（共享一份）；到期交易（含候选外的）
// 查为 expired 并移出待处理；确认块与账户确认序号不增加。
func assertRoundThreeEnded(t *testing.T, n *Node, local ProposalView, altID string, specs []round2Spec, confirmedBlock Block, keys []testKey) {
	t.Helper()

	if n.CurrentRound() != 3 {
		t.Fatalf("current round = %d, want 3", n.CurrentRound())
	}
	if n.Height() != 1 {
		t.Fatalf("confirmed height = %d, want 1 (EndRound adds no block)", n.Height())
	}
	blk, err := n.BlockAt(1)
	if err != nil {
		t.Fatal(err)
	}
	if blk != confirmedBlock {
		t.Fatalf("confirmed block changed: got %+v, want %+v", blk, confirmedBlock)
	}
	if latest, ok := n.LatestBlock(); !ok || latest != confirmedBlock {
		t.Fatalf("latest block = %+v ok=%v, want %+v", latest, ok, confirmedBlock)
	}

	// 旧轮标记未确认结束，两候选均落选，原投票仍可查询，未投票名单不变。
	rc, err := n.Candidates(2)
	if err != nil {
		t.Fatal(err)
	}
	if !rc.Ended || !rc.UnconfirmedEnd || !rc.HasRecords {
		t.Fatalf("round 2 must be an unconfirmed ended round with records: %+v", rc)
	}
	if len(rc.Candidates) != 2 {
		t.Fatalf("candidate count = %d, want 2", len(rc.Candidates))
	}
	wantUnvoted := hexKeys([][]byte{keys[2].pub, keys[3].pub})
	if got := hexKeys(rc.Unvoted); fmt.Sprint(got) != fmt.Sprint(wantUnvoted) {
		t.Fatalf("unvoted = %x, want %x", rc.Unvoted, [][]byte{keys[2].pub, keys[3].pub})
	}
	for _, c := range rc.Candidates {
		if c.Result != CandidateLost {
			t.Fatalf("candidate %s result = %s, want lost", c.BlockID, c.Result)
		}
		switch c.BlockID {
		case local.BlockID:
			if !c.Local {
				t.Fatalf("local candidate flag lost: %+v", c)
			}
			if len(c.Voters) != 1 || fmt.Sprintf("%x", c.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
				t.Fatalf("local candidate votes not retained: %x", c.Voters)
			}
		case altID:
			if len(c.Voters) != 1 || fmt.Sprintf("%x", c.Voters[0]) != fmt.Sprintf("%x", keys[1].pub) {
				t.Fatalf("competitor votes not retained: %x", c.Voters)
			}
		default:
			t.Fatalf("unexpected candidate %s", c.BlockID)
		}
	}

	// 交易结果：
	//   expiry <= 3 的（shared、altOnly? 见下、queuedExpire、gapExpire）-> expired，
	//   其余候选交易回到排队，候选外晚到期的保持排队。
	// 注意 specs[2]（alt-only）expiry=100，所以它作为竞争候选独有交易也必须回排队。
	for _, s := range specs {
		referenced := s.inLocal || s.inAlt
		expiresNow := s.expiry <= 3
		info := n.mustTx(t, s.tx.ID())
		switch {
		case expiresNow:
			if info.Status != StatusExpired {
				t.Fatalf("tx %s status = %s, want expired", s.content, info.Status)
			}
		case referenced:
			if info.Status != StatusQueued {
				t.Fatalf("tx %s status = %s, want queued (returned from lost candidates)", s.content, info.Status)
			}
		default:
			if info.Status != StatusQueued {
				t.Fatalf("tx %s status = %s, want queued", s.content, info.Status)
		}
		if info.BlockHeight != 0 || info.BlockID != "" {
			t.Fatalf("tx %s must not reference a block: height=%d block=%q",
				s.content, info.BlockHeight, info.BlockID)
		}
	}

	// 账户0：序号不推进（仍确认 seq1）；待处理仅余 seq3(localOnly) 与 seq5(sharedLate)
	// 排队等待打包；seq2、seq4 已过期移出池。最早缺口现在是 2。
	assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{
		specs[1].tx.ID(): "waiting-pack",
		specs[3].tx.ID(): "wait-pack-placeholder",
	})
	// 修正：sharedLate 同样是 waiting-pack。
	assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{
		specs[1].tx.ID(): "waiting-pack",
		specs[3].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[0].pub); a.Gap != 2 {
		t.Fatalf("account 0 gap after expiry = %d, want 2", a.Gap)
	}
	// 账户1：queuedExpire 过期移出，无待处理；确认序号仍 0，缺口为 1。
	if a := n.Account(keys[1].pub); a.ConfirmedSequence != 0 || len(a.Pending) != 0 || a.Gap != 1 {
		t.Fatalf("account 1 after expiry = %+v, want no pending, gap 1", a)
	}
	// 账户2：queuedLate 仍排队 waiting-pack，无缺口。
	assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
		specs[5].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[2].pub); a.Gap != 0 {
		t.Fatalf("account 2 gap = %d, want 0", a.Gap)
	}
	// 账户3：gapExpire(seq2) 过期，gapLate(seq3) 仍排队；缺口仍是 1。
	assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{
		specs[7].tx.ID(): "waiting-pack",
	})
	if a := n.Account(keys[3].pub); a.Gap != 1 {
		t.Fatalf("account 3 gap = %d, want 1", a.Gap)
	}
}

// TestEndRoundSaveFailureAtomic 覆盖主动结束未确认轮次保存失败的完整回归序列：
// 已有确认历史的第 2 轮，两个持票但未决的候选（含共享与独有交易、候选外排队交易、
// 恰好下一轮到期与晚到期两种到期轮次）；失败的 EndRound 整体不生效（内存/磁盘/
// 重开三处一致，返回轮次为 0），恢复后再次结束才落选、回排队、过期且不留块。
func TestEndRoundSaveFailureAtomic(t *testing.T) {
	keys := genKeys(t, 4)
	n, dir := newTestNode(t, keys, 10)

	// 第 1 轮确认历史：账户0 seq1 上链，高度 1；之后节点处于第 2 轮。
	hist := NewTransaction(keys[0].priv, 1, []byte("round1-confirmed"), 5, 100)
	if _, err := n.Submit(hist); err != nil {
		t.Fatal(err)
	}
	p1, err := n.Propose()
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprint(p1.TxIDs) != fmt.Sprint([]string{hist.ID()}) {
		t.Fatalf("setup: round 1 proposal = %v, want [%s]", p1.TxIDs, hist.ID())
	}
	confirmCandidate(t, n, keys, p1.BlockID)
	if n.CurrentRound() != 2 || n.Height() != 1 {
		t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
	}
	confirmedBlock, err := n.BlockAt(1)
	if err != nil {
		t.Fatal(err)
	}

	// 第 2 轮未决场景。
	local, altID, specs := buildRoundTwoPending(t, n, keys)
	assertRoundTwoPending(t, n, local, altID, specs, confirmedBlock, keys)

	// 快照结束前的磁盘文件：失败的保存不得改写它，也不得残留临时文件。
	statePath := filepath.Join(dir, stateFileName)
	before, err := os.ReadFile(statePath)
	if err != nil {
		t.Fatal(err)
	}

	// 主动结束因状态写入失败而返回错误，返回轮次必须为 0。
	n.injectSaveErr = errors.New("disk full (simulated)")
	nextRound, err := n.EndRound()
	n.injectSaveErr = nil
	if err == nil {
		t.Fatal("EndRound must return an error when saving node state fails")
	}
	if reason(err) != "" {
		t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
	}
	if nextRound != 0 {
		t.Fatalf("EndRound return round = %d, want 0 on save failure", nextRound)
	}

	// 内存：候选、票、交易（proposed 不回排队、queued 不过期）、账户、确认块全部照旧。
	assertRoundTwoPending(t, n, local, altID, specs, confirmedBlock, keys)

	// 磁盘：状态文件逐字节不变，目录内不残留 .tmp。
	after, err := os.ReadFile(statePath)
	if err != nil {
		t.Fatal(err)
	}
	if string(after) != string(before) {
		t.Fatal("state file changed despite the failed save")
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, e := range entries {
		names = append(names, e.Name())
	}
	if fmt.Sprint(names) != "[state.json]" {
		t.Fatalf("failed save must not leave temp files, dir contains %v", names)
	}

	// 重开节点：看到同样的未结束状态，保存记录里没有本次结束造成的任何变化。
	reopened, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	assertRoundTwoPending(t, reopened, local, altID, specs, confirmedBlock, keys)

	// 保存恢复正常后，在仍处于原轮次（第 2 轮）的节点上再次结束，才进入第 3 轮。
	nextRound, err = reopened.EndRound()
	if err != nil {
		t.Fatalf("EndRound after recovery failed: %v", err)
	}
	if nextRound != 3 {
		t.Fatalf("EndRound after recovery = %d, want 3", nextRound)
	}
	assertRoundThreeEnded(t, reopened, local, altID, specs, confirmedBlock, keys)

	// 第二次成功的结束同样持久化：再开一次看到的是完全一致的第 3 轮状态。
	durable, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	assertRoundThreeEnded(t, durable, local, altID, specs, confirmedBlock, keys)
}

